<script setup>
import {ref,onMounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,auth} from '../api'
import {money,date,productStates,places,safeImage} from '../domain'
const route=useRoute(),router=useRouter(),product=ref(null),error=ref(''),busy=ref(false),loading=ref(true),imageIndex=ref(0),failed=ref(false),contact=ref(''),place=ref(''),notice=ref('')
const own=computed(()=>product.value?.seller.id===auth.user?.id)
async function load(){loading.value=true;error.value='';try{product.value=await api(`/products/${route.params.id}`);contact.value=auth.user?.contact||''}catch(e){error.value=e.message}finally{loading.value=false}}
async function action(type){if(busy.value)return;if(['reserve','delist','reshelf'].includes(type)&&!window.confirm({reserve:'确认预订这件商品？请与卖家线下沟通面交。',delist:'确认下架这件商品？',reshelf:'确认重新上架？'}[type]))return;busy.value=true;error.value='';notice.value='';try{
if(type==='favorite'){await api(`/favorites/${product.value.id}`,{method:product.value.is_favorite?'DELETE':'POST'});product.value.is_favorite=!product.value.is_favorite}
else if(type==='reserve'){await api('/orders',{method:'POST',body:{product_id:product.value.id,place_id:place.value?Number(place.value):null,contact:contact.value||null}});router.push('/orders')}
else{await api(`/products/${product.value.id}/${type}`,{method:'POST'});await load();notice.value='操作成功'}
}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><RouterLink to="/" class="back-link">← 返回好物集市</RouterLink><div v-if="loading" class="empty">正在加载商品…</div><p v-if="error" class="error" role="alert">{{error}} <button v-if="!product" @click="load">重试</button></p><p v-if="notice" class="success">{{notice}}</p><section v-if="product" class="detail-grid"><div class="panel"><div class="detail-image"><img v-if="safeImage(product.images[imageIndex])&&!failed" :src="safeImage(product.images[imageIndex])" :alt="product.title" @error="failed=true"><div v-else class="cover-placeholder"><span>{{product.category_name}}</span><small>暂无可用图片</small></div></div><div class="thumbs"><button v-for="(_,i) in product.images" :key="i" :class="{selected:imageIndex===i}" @click="imageIndex=i;failed=false">图片 {{i+1}}</button></div></div><div class="panel detail-copy"><p class="eyebrow">{{product.category_name}} / {{product.condition_name}}</p><span class="pill">{{productStates[product.status]}}</span><h1>{{product.title}}</h1><p class="detail-price">¥ {{money(product.price)}}</p><p class="description">{{product.description||'卖家暂未填写描述。'}}</p><dl><dt>发布者</dt><dd>{{product.seller.nickname}}</dd><dt>交易地点</dt><dd>{{product.place_name||'双方商议'}}</dd><dt>卖家联系方式</dt><dd>{{product.seller.contact||'暂未填写'}}</dd><dt>发布时间</dt><dd>{{date(product.created_at)}}</dd><dt>浏览次数</dt><dd>{{product.view_count}}</dd></dl><div v-if="!own&&product.status===1"><label>面交地点<select v-model="place"><option value="">与卖家商议</option><option v-for="(name,i) in places" :key="name" :value="i+1">{{name}}</option></select></label><label>你的联系方式<input v-model.trim="contact" maxlength="100" placeholder="便于卖家与你联系"></label></div><div class="actions"><button v-if="!own&&product.status===1" class="primary" :disabled="busy||!auth.user" @click="action('reserve')">预订这件好物</button><button :disabled="busy" @click="action('favorite')">{{product.is_favorite?'♥ 已收藏 · 取消':'♡ 收藏商品'}}</button><RouterLink v-if="own&&product.status!==4" :to="`/products/${product.id}/edit`" class="button">编辑商品</RouterLink><button v-if="(own||auth.user?.is_admin)&&product.status!==4" :disabled="busy" @click="action('delist')">下架</button><button v-if="auth.user?.is_admin&&product.status===4" :disabled="busy" @click="action('reshelf')">重新上架</button></div></div></section></template>
